 */
static inline int bluetil_ad_add_name(bluetil_ad_t *ad, const char *name)
{
    return bluetil_ad_add(ad, BLE_GAP_AD_NAME, name, strlen(name));
}

/**
 * @brief   Convenience function for initializing the advertising data
