                DEBUG("usbus_control: activated endpoint %d, dir %s\n",
                      ep->ep->num,
                      ep->ep->dir == USB_EP_DIR_OUT ? "out" : "in");
            }
        }
        for (usbus_interface_alt_t *alt = iface->alts; alt; alt = alt->next) {
            for (usbus_endpoint_t *ep = alt->ep; ep; ep = ep->next) {
                if (ep->active) {
